let count = 0;
for (const item of geneware) {
  const slug = item.name.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');
  const data = {
    name: item.name,
    type: "geneware",
    aliases: item.aliases,
    category: item.category,
    target_system: item.target_system,
    description: item.description,
    source_organism: item.source_organism,
    manufacturer: item.manufacturer,
    tier_availability: item.tier_availability,
    legality: item.legality,
    procedure: item.procedure,
    expression_time: item.expression_time,
    reversibility: item.reversibility,
    side_effects: item.side_effects,
    social_perception: item.social_perception,
    story_hooks: item.story_hooks
  };
  fs.writeFileSync(path.join(outDir, `${slug}.json`), JSON.stringify(data, null, 2));
  count++;
}

